#!/usr/bin/env bash
# TK-493 F8 (S1, П-37 r3.1): волна 2. Запуск - ТОЛЬКО по команде CEO (S1 не запускал); cd ~/xdl9/sel/waves; THREADS=4 nice -n 19 bash wave2.sh
# Перед первым запуском: выписка В-213 «есть / считаем / стоимость»; каталоги out/ и d2/ не существуют.
set -u
THREADS=${THREADS:-4}
tj() { seq -s, 0 $(( $(wc -l < "$1") - 2 )); }       # номера заданий 0..n-1 (в файле заголовок + n строк)
mkdir -p out/w2
$HOME/xdl9/bin/statarb-xdl9-4ef45cc8 statarb run --kind pair --panels $HOME/xdl9/trade/binance --funding-y $HOME/xdl9/funding/binance --rearm --cells w2/A1_binance_crypto.cells.csv --jobs w2/A1_binance_crypto__binance__binance.jobs.csv --daily-out out/w2/A1_binance_crypto__binance__binance.daily.csv --trades-out out/w2/A1_binance_crypto__binance__binance.trades.csv --trades-ext --trade-jobs "$(tj w2/A1_binance_crypto__binance__binance.jobs.csv)" --open-out out/w2/A1_binance_crypto__binance__binance.open.csv --mtm-open --cells-out out/w2/A1_binance_crypto__binance__binance.cells_out.csv --ext-out out/w2/A1_binance_crypto__binance__binance.ext.csv --job-day-out out/w2/A1_binance_crypto__binance__binance.jobday.csv --min-span 1440 --threads ${THREADS:-4}
$HOME/xdl9/bin/statarb-xdl9-4ef45cc8 statarb run --kind pair --panels $HOME/xdl9/trade/bingx --funding-y $HOME/xdl9/funding/bingx --rearm --cells w2/A1_bingx_crypto.cells.csv --jobs w2/A1_bingx_crypto__bingx__bingx.jobs.csv --daily-out out/w2/A1_bingx_crypto__bingx__bingx.daily.csv --trades-out out/w2/A1_bingx_crypto__bingx__bingx.trades.csv --trades-ext --trade-jobs "$(tj w2/A1_bingx_crypto__bingx__bingx.jobs.csv)" --open-out out/w2/A1_bingx_crypto__bingx__bingx.open.csv --mtm-open --cells-out out/w2/A1_bingx_crypto__bingx__bingx.cells_out.csv --ext-out out/w2/A1_bingx_crypto__bingx__bingx.ext.csv --job-day-out out/w2/A1_bingx_crypto__bingx__bingx.jobday.csv --min-span 1440 --threads ${THREADS:-4}
$HOME/xdl9/bin/statarb-xdl9-4ef45cc8 statarb run --kind pair --panels $HOME/xdl9/trade/bingx --funding-y $HOME/xdl9/funding/bingx --rearm --cells w2/A1_bingx_eq_us.cells.csv --jobs w2/A1_bingx_eq_us__bingx__bingx.jobs.csv --daily-out out/w2/A1_bingx_eq_us__bingx__bingx.daily.csv --trades-out out/w2/A1_bingx_eq_us__bingx__bingx.trades.csv --trades-ext --trade-jobs "$(tj w2/A1_bingx_eq_us__bingx__bingx.jobs.csv)" --open-out out/w2/A1_bingx_eq_us__bingx__bingx.open.csv --mtm-open --cells-out out/w2/A1_bingx_eq_us__bingx__bingx.cells_out.csv --ext-out out/w2/A1_bingx_eq_us__bingx__bingx.ext.csv --job-day-out out/w2/A1_bingx_eq_us__bingx__bingx.jobday.csv --min-span 1440 --threads ${THREADS:-4}
$HOME/xdl9/bin/statarb-xdl9-4ef45cc8 statarb run --kind pair --panels $HOME/xdl9/trade/okx --funding-y $HOME/xdl9/funding/okx --rearm --cells w2/A1_okx_crypto.cells.csv --jobs w2/A1_okx_crypto__okx__okx.jobs.csv --daily-out out/w2/A1_okx_crypto__okx__okx.daily.csv --trades-out out/w2/A1_okx_crypto__okx__okx.trades.csv --trades-ext --trade-jobs "$(tj w2/A1_okx_crypto__okx__okx.jobs.csv)" --open-out out/w2/A1_okx_crypto__okx__okx.open.csv --mtm-open --cells-out out/w2/A1_okx_crypto__okx__okx.cells_out.csv --ext-out out/w2/A1_okx_crypto__okx__okx.ext.csv --job-day-out out/w2/A1_okx_crypto__okx__okx.jobday.csv --min-span 1440 --threads ${THREADS:-4}
